package com.stocksense.ledger; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Sort; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/movements") @RequiredArgsConstructor public class LedgerController { private final StockMovementRepository repo; @GetMapping public List<StockMovement> all(){return repo.findAll(Sort.by(Sort.Direction.DESC,"createdAt"));} }
